"""Render the comparison reports as JSON and Markdown traces.

Leads with the placement-vs-trigger distinction, which is the research concern:
where an autonomous opportunity is allowed to execute (relative to the main
human conversation) is a separate axis from which trigger policy proposed it.

Output is labelled throughout as a HYPOTHETICAL packet generated by this lab,
NOT a captured Claude Code request.
"""

import json

import run_session as rs

DISCLAIMER = (
    "HYPOTHETICAL PACKET generated by cc-context-lab's offline companion-input "
    "lab. NOT a captured Claude Code request. No model, clock, network, or real "
    "message delivery is involved; all outcomes are pre-scripted fixture inputs."
)

def render_json(fx, base, placements):
    out = {
        "disclaimer": DISCLAIMER,
        "scenario_id": fx.scenario_id,
        "assumptions": fx.scenario_assumptions,
        "shared": fx.shared,
        "source_archive": fx.occurrences,
        "time_format": "elapsed HH:MM:SS; raw fixture and candidate times are seconds",
        "axis_note": (
            "Two independent axes: trigger policy (when an opportunity arises) "
            "and placement rule (where it may execute relative to chat_active). "
            "Trigger owner/location != execution target; turn_busy != chat_active; "
            "independent same-session history is the independent session's OWN."
        ),
        "placements": [
            {"id": p["id"], "rule": p["rule"], "target": p["target"],
             "label": p["label"], "assumptions": p["assumptions"]}
            for p in fx.placements
        ],
        "base_comparison": {},          # all policies, main_defer, same/fresh
        "placement_comparison": {},     # fixed/hybrid x all placements
        "outcomes": fx.outcomes,
    }
    for pid, modes in base.items():
        out["base_comparison"][pid] = _report_json(modes)
    for pid, pls in placements.items():
        out["placement_comparison"][pid] = {
            plid: _report_json(modes) for plid, modes in pls.items()
        }
    return json.dumps(out, ensure_ascii=False, indent=2) + "\n"

def _report_json(modes):
    return {m: {
        "wakes": [
            {
                "candidate_id": w["id"],
                "trigger_owner_kind": w["owner_kind"],
                "trigger_owner_detail": w["owner_detail"],
                "execution_target": w["execution_target"],
                "trigger_time": rs.format_time(w["trigger_time"]),
                "actual_start": rs.format_time(w["actual_start"]),
                "reasons": w["reasons"],
                "deferred": w["deferred"],
                "coalesced": w["coalesced"],
                "coalesced_trigger_ids": w.get("coalesced_trigger_ids", []),
                "turn_busy_at_trigger": w.get("turn_busy_at_trigger"),
                "chat_active_at_trigger": w.get("chat_active_at_trigger"),
                "placement_reason": w.get("placement_reason"),
            }
            for w in rep["wakes"]
        ],
        "audit": rep["audit"],
        "packets": rep["packets"],
    } for m, rep in modes.items()}

def _fmt(xs):
    return ", ".join(str(x) for x in xs) if xs else "(none)"

def _render_modes(w, label, modes):
    for mode in ("same", "fresh"):
        rep = modes[mode]
        w("#### %s — history mode `%s`" % (label, mode))
        w("")
        if mode == "same":
            w("Same-session history = the executing session's OWN previously "
              "emitted material only; fixture source availability is not prior "
              "delivery. Not conflated with the main conversation.")
        else:
            w("Fresh session with explicit bounded carryover: only wake-named ids "
              "plus any fixture read-only main snapshot.")
        w("")
        w("Audit: `%s`" % json.dumps(rep["audit"], ensure_ascii=False, sort_keys=True))
        w("")
        for pkt in rep["packets"]:
            wk = pkt["wake"]
            w("- **wake `%s`** owner=`%s/%s` → target=`%s` | trigger %s → start %s"
              % (wk["candidate_id"], wk["trigger_owner_kind"], wk["trigger_owner_detail"],
                 pkt["execution_target"], wk["trigger_time"], wk["actual_start"]))
            w("  - reasons: %s" % _fmt(wk["scheduled_reasons"]))
            w("  - turn_busy_at_trigger=%s chat_active_at_trigger=%s placement=%s"
              % (wk["turn_busy_at_trigger"], wk["chat_active_at_trigger"],
                 wk["placement_reason"]))
            if wk["deferred"]:
                w("  - **deferred** (placement rule defers/rechecks; selection redone "
                  "at actual start)")
            if wk["coalesced"]:
                w("  - **coalesced burst** — contributing ids preserved: %s"
                  % _fmt(wk["coalesced_trigger_ids"]))
            w("  - included ids: %s" % _fmt([i["id"] for i in pkt["included"]]))
            w("  - excluded ids+reasons: %s"
              % _fmt(["%s (%s)" % (e["id"], e["reason"]) for e in pkt["excluded"]]))
            w("  - fresh ambient: %s"
              % _fmt(["%s obs=%s exp=%s — %s" % (a["id"], a["observed_at"], a["expires_at"], a["text"])
                      for a in pkt["fresh_ambient_blocks"]]))
            w("  - memory (current): %s" % _fmt([m["id"] + ": " + m["text"] for m in pkt["memory_items"]]))
            for u in pkt["user_text_blocks"]:
                w("  - **exact user text** [%s] (%s channel=`%s` sender=`%s` reply=`%s` "
                  "attachment=`%s`):" % (u["id"], u["origin"], u["wrapper"]["channel"],
                  u["wrapper"]["sender"], u["wrapper"]["reply_target"], u["wrapper"]["attachment"]))
                w("    > %s" % u["exact_user_text"])
            w("  - passive recall (fixture-supplied, no backend): %s"
              % _fmt([r["id"] + " source=" + str(r["source_memory_id"]) + ": " + r["body"] for r in pkt["passive_recall_blocks"]]))
            w("  - internal-only results: %s ; delivered=true ids: %s"
              % (_fmt([i["id"] + ": " + i["body"] for i in pkt["internal_result_blocks"]]),
                 _fmt([i["id"] for i in pkt["internal_result_blocks"] if i["delivered"]])))
            for o in pkt["scripted_outcomes"]:
                w("  - **scripted post-turn outcome**: `%s`; external_delivery=`%s`; next plan=`%s`"
                  % (o.get("scripted_outcome"), o.get("external_delivery", "n/a"), o.get("next_wake_plan", "n/a")))
            w("  - produced AFTER this input: %s" % _fmt([
                b["id"] + ": " + b["body"] for b in pkt["scripted_produced_results"]]))
            w("  - carried historical material (not asserted current):")
            for c in pkt["carried_history_or_carryover"]:
                w("    - %s (%s): %s" % (c["id"], c["kind"],
                    json.dumps(c, ensure_ascii=False, sort_keys=True)))
        w("")

def render_markdown(fx, base, placements):
    L = []
    w = L.append
    w("# Companion input lab — %s" % fx.scenario_id)
    w("")
    w("> %s" % DISCLAIMER)
    w("")
    w("## 两个独立轴：trigger 与 placement（先读这一节）")
    w("")
    w("**触发轴（trigger policy）** 只回答“自主机会何时出现”：固定间隔、列举抖动间隔、"
      "事件驱动、自调度 one-shot、idle 窗口、hybrid。")
    w("")
    w("**放置轴（placement rule）** 回答“机会被允许在哪里执行”，相对主对话而言：")
    w("")
    w("- `main_skip`：chat_active 期间的自主机会被**跳过**（记录进 audit，不执行）。")
    w("- `main_defer`：chat_active 期间的机会**合并**为一次 wake，在 chat_active 结束后"
      "**重新选择/重建**（不是仅在某个 turn_busy 结束后）。")
    w("- `independent`：chat_active 期间在**独立自主会话**执行，该会话有自己的历史；"
      "**不写入、不注入主对话**。")
    w("")
    w("**关键区分（研究关注点）：**")
    w("")
    w("- **trigger owner/location ≠ execution target**：外部 timer 仍可 target main；"
      "外部 trigger 不蕴含独立执行。两者都单独 trace。")
    w("- **turn_busy ≠ chat_active**：turn_busy 是一个 turn/response 仍在跑；"
      "chat_active 是**显式供给**的“人类对话跨轮仍在进行”。"
      "**不**因为模型结束一次回复就推断 chat 已停。")
    w("- **same_session ≠ main_session**：independent 的 same 历史是它**自己**累积的历史；"
      "主对话快照只有 fixture 显式列为只读输入时才出现。")
    w("")
    w("`main_skip` / `main_defer` / `independent` 是**本 lab 的选择，不是真实上游默认**；"
      "不选生产偏好，三者分别比较。")
    w("")
    w("**Scenario:** %s" % fx.description)
    w("")
    if fx.scenario_assumptions:
        w("**Fixture assumptions:** %s" % fx.scenario_assumptions)
        w("")
    w("**Shared:** %s" % json.dumps(fx.shared, ensure_ascii=False, sort_keys=True))
    w("")
    w("All displayed times are elapsed `HH:MM:SS`; fixture/candidate raw times are seconds.")
    w("")

    w("## 一次 turn 已结束、聊天仍在进行的对照")
    w("")
    w("| placement | 自主候选时间 | actual start / 跳过 | target |")
    w("| --- | --- | --- | --- |")
    pid = "P1_fixed_interval"
    gap_candidates = [c for c in rs.generate_candidates(fx, next(p for p in fx.policies if p["id"] == pid))
                      if fx.in_chat(c["trigger_time"]) and not fx.in_busy(c["trigger_time"], "main")]
    if gap_candidates:
        c = gap_candidates[0]
        for plid, modes in placements[pid].items():
            rep = modes["same"]
            match = next((wk for wk in rep["wakes"] if any(x["id"] == c["id"] for x in wk["candidates"])), None)
            result = rs.format_time(match["actual_start"]) if match else "跳过"
            target = match["execution_target"] if match else "main"
            w("| %s | %s | %s | %s |" % (plid, rs.format_time(c["trigger_time"]), result, target))
    w("")
    w("这三行比较的是自主候选；普通人类消息的主聊天回复循环不在本实验里。")
    w("")
    w("## 基准比较：六 policy × `main_defer` × {same, fresh}")
    w("")
    for policy in fx.policies:
        pid = policy["id"]
        w("### `%s` — %s" % (pid, policy.get("label", policy["kind"])))
        w("")
        w("Trigger assumptions: %s" % policy.get("assumptions", ""))
        w("")
        _render_modes(w, pid, base[pid])

    w("## 放置比较（聚焦）：`P1_fixed_interval` 与 `P6_hybrid` × 三条 placement")
    w("")
    for pid, pls in placements.items():
        w("### policy `%s`" % pid)
        w("")
        for pl in fx.placements:
            plid = pl["id"]
            if plid not in pls:
                continue
            w("#### placement `%s` (%s → target `%s`)" % (plid, pl["rule"], pl["target"]))
            w("")
            w("Assumptions: %s" % pl["assumptions"])
            w("")
            _render_modes(w, "%s/%s" % (pid, plid), pls[plid])

    w("## 预写 outcome（输入，不是模型响应）")
    w("")
    w("| trigger | scope | scripted outcome | external delivery | next wake plan |")
    w("| --- | --- | --- | --- | --- |")
    for o in fx.outcomes:
        w("| `%s` | %s | %s | %s | %s |"
          % (o["trigger"], o.get("wake_scope", "n/a"), o.get("scripted_outcome", ""),
             o.get("external_delivery", "n/a"), o.get("next_wake_plan", "n/a")))
    w("")
    return "\n".join(L) + "\n"
